sigset_t block_mask, old_mask;

// 1. Initialize set of signals to block
sigemptyset(&block_mask);
sigaddset(&block_mask, SIGUSR1);
sigaddset(&block_mask, SIGUSR2);

// 2. Block signals (SIG_BLOCK), saving the current mask in old_mask
rt_sigprocmask(SIG_BLOCK, &block_mask, &old_mask);

// ... Protected execution context ...

// 3. Restore previous mask (SIG_SETMASK)
rt_sigprocmask(SIG_SETMASK, &old_mask, NULL);
